import { ISequence, ITimeout, SequenceDiff } from '../algorithms/diffAlgorithm.js';
import { MyersDiffAlgorithm } from '../algorithms/myersDiffAlgorithm.js';
import { findLastMonotonous } from '../core/arraysFind.js';
import { LineRangeSet } from './lineRangeSet.js';
import { DetailedLineRangeMapping, LineRange, LineRangeMapping } from './rangeMapping.js';

/**
 * Detects blocks of lines that were moved. Ported from VS Code
 * (`src/vs/editor/common/diff/defaultLinesDiffComputer/computeMovedLines.ts`)
 * and kept behaviorally identical, so both produce the same moves, except that
 * extending a move upwards stops at the first line instead of throwing.
 */
export function computeMovedLines(
	changes: DetailedLineRangeMapping[],
	originalLines: string[],
	modifiedLines: string[],
	hashedOriginalLines: number[],
	hashedModifiedLines: number[],
	timeout: ITimeout,
): LineRangeMapping[] {
	let { moves, excludedChanges } = computeMovesFromSimpleDeletionsToSimpleInsertions(changes, originalLines, modifiedLines, timeout);

	if (!timeout.isValid()) { return []; }

	const filteredChanges = changes.filter(c => !excludedChanges.has(c));
	const unchangedMoves = computeUnchangedMoves(filteredChanges, hashedOriginalLines, hashedModifiedLines, originalLines, modifiedLines, timeout);
	moves.push(...unchangedMoves);

	moves = joinCloseConsecutiveMoves(moves);
	// Ignore too short moves
	moves = moves.filter(current => {
		const lines = originalLines.slice(current.original.startLineNumber - 1, current.original.endLineNumberExclusive - 1).map(l => l.trim());
		const originalText = lines.join('\n');
		return originalText.length >= 15 && lines.filter(l => l.length >= 2).length >= 2;
	});
	moves = removeMovesInSameDiff(changes, moves);

	return moves;
}

function computeMovesFromSimpleDeletionsToSimpleInsertions(
	changes: DetailedLineRangeMapping[],
	originalLines: string[],
	modifiedLines: string[],
	timeout: ITimeout,
) {
	const moves: LineRangeMapping[] = [];

	const deletions = changes
		.filter(c => c.modified.isEmpty && c.original.length >= 3)
		.map(d => new LineRangeFragment(d.original, originalLines, d));
	const insertions = new Set(changes
		.filter(c => c.original.isEmpty && c.modified.length >= 3)
		.map(d => new LineRangeFragment(d.modified, modifiedLines, d)));

	const excludedChanges = new Set<DetailedLineRangeMapping>();

	for (const deletion of deletions) {
		let highestSimilarity = -1;
		let best: LineRangeFragment | undefined;
		for (const insertion of insertions) {
			const similarity = deletion.computeSimilarity(insertion);
			if (similarity > highestSimilarity) {
				highestSimilarity = similarity;
				best = insertion;
			}
		}

		if (highestSimilarity > 0.90 && best) {
			insertions.delete(best);
			moves.push(new LineRangeMapping(deletion.range, best.range));
			excludedChanges.add(deletion.source);
			excludedChanges.add(best.source);
		}

		if (!timeout.isValid()) {
			return { moves, excludedChanges };
		}
	}

	return { moves, excludedChanges };
}

function computeUnchangedMoves(
	changes: DetailedLineRangeMapping[],
	hashedOriginalLines: number[],
	hashedModifiedLines: number[],
	originalLines: string[],
	modifiedLines: string[],
	timeout: ITimeout,
) {
	const moves: LineRangeMapping[] = [];

	const original3LineHashes = new Map<string, LineRange[]>();
	for (const change of changes) {
		for (let i = change.original.startLineNumber; i < change.original.endLineNumberExclusive - 2; i++) {
			const key = `${hashedOriginalLines[i - 1]}:${hashedOriginalLines[i + 1 - 1]}:${hashedOriginalLines[i + 2 - 1]}`;
			let ranges = original3LineHashes.get(key);
			if (!ranges) {
				ranges = [];
				original3LineHashes.set(key, ranges);
			}
			ranges.push(new LineRange(i, i + 3));
		}
	}

	interface PossibleMapping {
		modifiedLineRange: LineRange;
		originalLineRange: LineRange;
	}

	const possibleMappings: PossibleMapping[] = [];

	changes.sort((a, b) => a.modified.startLineNumber - b.modified.startLineNumber);

	for (const change of changes) {
		let lastMappings: PossibleMapping[] = [];
		for (let i = change.modified.startLineNumber; i < change.modified.endLineNumberExclusive - 2; i++) {
			const key = `${hashedModifiedLines[i - 1]}:${hashedModifiedLines[i + 1 - 1]}:${hashedModifiedLines[i + 2 - 1]}`;
			const currentModifiedRange = new LineRange(i, i + 3);

			const nextMappings: PossibleMapping[] = [];
			for (const range of original3LineHashes.get(key) ?? []) {
				// Does this match extend one of the matches of the previous line?
				const extended = lastMappings.find(lastMapping =>
					lastMapping.originalLineRange.endLineNumberExclusive + 1 === range.endLineNumberExclusive &&
					lastMapping.modifiedLineRange.endLineNumberExclusive + 1 === currentModifiedRange.endLineNumberExclusive);
				if (extended) {
					extended.originalLineRange = new LineRange(extended.originalLineRange.startLineNumber, range.endLineNumberExclusive);
					extended.modifiedLineRange = new LineRange(extended.modifiedLineRange.startLineNumber, currentModifiedRange.endLineNumberExclusive);
					nextMappings.push(extended);
					continue;
				}

				const mapping: PossibleMapping = {
					modifiedLineRange: currentModifiedRange,
					originalLineRange: range,
				};
				possibleMappings.push(mapping);
				nextMappings.push(mapping);
			}
			lastMappings = nextMappings;
		}

		if (!timeout.isValid()) {
			return [];
		}
	}

	// Stable sort, longest first.
	possibleMappings.sort((a, b) => b.modifiedLineRange.length - a.modifiedLineRange.length);

	const modifiedSet = new LineRangeSet();
	const originalSet = new LineRangeSet();

	for (const mapping of possibleMappings) {
		const diffOrigToMod = mapping.modifiedLineRange.startLineNumber - mapping.originalLineRange.startLineNumber;
		const modifiedSections = modifiedSet.subtractFrom(mapping.modifiedLineRange);
		const originalTranslatedSections = originalSet.subtractFrom(mapping.originalLineRange).getWithDelta(diffOrigToMod);

		const modifiedIntersectedSections = modifiedSections.getIntersection(originalTranslatedSections);

		for (const s of modifiedIntersectedSections.ranges) {
			if (s.length < 3) {
				continue;
			}
			const modifiedLineRange = s;
			const originalLineRange = s.delta(-diffOrigToMod);

			moves.push(new LineRangeMapping(originalLineRange, modifiedLineRange));

			modifiedSet.addRange(modifiedLineRange);
			originalSet.addRange(originalLineRange);
		}
	}

	moves.sort((a, b) => a.original.startLineNumber - b.original.startLineNumber);

	for (let i = 0; i < moves.length; i++) {
		const move = moves[i];
		const firstTouchingChangeOrig = findLastMonotonous(changes, c => c.original.startLineNumber <= move.original.startLineNumber)!;
		const firstTouchingChangeMod = findLastMonotonous(changes, c => c.modified.startLineNumber <= move.modified.startLineNumber)!;
		const linesAbove = Math.max(
			move.original.startLineNumber - firstTouchingChangeOrig.original.startLineNumber,
			move.modified.startLineNumber - firstTouchingChangeMod.modified.startLineNumber
		);

		const lastTouchingChangeOrig = findLastMonotonous(changes, c => c.original.startLineNumber < move.original.endLineNumberExclusive)!;
		const lastTouchingChangeMod = findLastMonotonous(changes, c => c.modified.startLineNumber < move.modified.endLineNumberExclusive)!;
		const linesBelow = Math.max(
			lastTouchingChangeOrig.original.endLineNumberExclusive - move.original.endLineNumberExclusive,
			lastTouchingChangeMod.modified.endLineNumberExclusive - move.modified.endLineNumberExclusive
		);

		let extendToTop: number;
		for (extendToTop = 0; extendToTop < linesAbove; extendToTop++) {
			const origLine = move.original.startLineNumber - extendToTop - 1;
			const modLine = move.modified.startLineNumber - extendToTop - 1;
			// VS Code lacks this check and throws when a move starts in the first line on one side only.
			if (origLine < 1 || modLine < 1) {
				break;
			}
			if (modifiedSet.contains(modLine) || originalSet.contains(origLine)) {
				break;
			}
			if (!areLinesSimilar(originalLines[origLine - 1], modifiedLines[modLine - 1], timeout)) {
				break;
			}
		}

		if (extendToTop > 0) {
			originalSet.addRange(new LineRange(move.original.startLineNumber - extendToTop, move.original.startLineNumber));
			modifiedSet.addRange(new LineRange(move.modified.startLineNumber - extendToTop, move.modified.startLineNumber));
		}

		let extendToBottom: number;
		for (extendToBottom = 0; extendToBottom < linesBelow; extendToBottom++) {
			const origLine = move.original.endLineNumberExclusive + extendToBottom;
			const modLine = move.modified.endLineNumberExclusive + extendToBottom;
			if (origLine > originalLines.length || modLine > modifiedLines.length) {
				break;
			}
			if (modifiedSet.contains(modLine) || originalSet.contains(origLine)) {
				break;
			}
			if (!areLinesSimilar(originalLines[origLine - 1], modifiedLines[modLine - 1], timeout)) {
				break;
			}
		}

		if (extendToBottom > 0) {
			originalSet.addRange(new LineRange(move.original.endLineNumberExclusive, move.original.endLineNumberExclusive + extendToBottom));
			modifiedSet.addRange(new LineRange(move.modified.endLineNumberExclusive, move.modified.endLineNumberExclusive + extendToBottom));
		}

		if (extendToTop > 0 || extendToBottom > 0) {
			moves[i] = new LineRangeMapping(
				new LineRange(move.original.startLineNumber - extendToTop, move.original.endLineNumberExclusive + extendToBottom),
				new LineRange(move.modified.startLineNumber - extendToTop, move.modified.endLineNumberExclusive + extendToBottom),
			);
		}
	}

	return moves;
}

/**
 * Note: this reproduces VS Code's heuristic exactly, including its quirks:
 * the characters are diffed without leading/trailing whitespace and without the
 * last character of the line, while the counting below indexes into the untrimmed lines.
 */
function areLinesSimilar(line1: string, line2: string, timeout: ITimeout): boolean {
	if (line1.trim() === line2.trim()) { return true; }
	if (line1.length > 300 && line2.length > 300) { return false; }

	const myersDiffingAlgorithm = new MyersDiffAlgorithm();
	const result = myersDiffingAlgorithm.compute(
		new TrimmedLineCharSequence(line1),
		new TrimmedLineCharSequence(line2),
		timeout
	);
	let commonNonSpaceCharCount = 0;
	const inverted = SequenceDiff.invert(result.diffs, line1.length);
	for (const seq of inverted) {
		for (let idx = seq.seq1Range.start; idx < seq.seq1Range.endExclusive; idx++) {
			if (!isSpace(line1.charCodeAt(idx))) {
				commonNonSpaceCharCount++;
			}
		}
	}

	function countNonWsChars(str: string): number {
		let count = 0;
		for (let i = 0; i < line1.length; i++) {
			if (!isSpace(str.charCodeAt(i))) {
				count++;
			}
		}
		return count;
	}

	const longerLineLength = countNonWsChars(line1.length > line2.length ? line1 : line2);
	return commonNonSpaceCharCount / longerLineLength > 0.6 && longerLineLength > 10;
}

/**
 * The characters of a line without leading/trailing whitespace, cut off at
 * `line.length - 1` (counted in the untrimmed line), like VS Code's
 * `new LinesSliceCharSequence([line], new Range(1, 1, 1, line.length), false)`.
 */
class TrimmedLineCharSequence implements ISequence {
	private readonly _text: string;

	constructor(line: string) {
		const trimmedStart = line.trimStart();
		const leadingWhitespace = line.length - trimmedStart.length;
		const trimmed = trimmedStart.trimEnd();
		this._text = trimmed.substring(0, Math.max(0, Math.min(line.length - 1 - leadingWhitespace, trimmed.length)));
	}

	get length(): number {
		return this._text.length;
	}

	getElement(offset: number): number {
		return this._text.charCodeAt(offset);
	}

	isStronglyEqual(offset1: number, offset2: number): boolean {
		return this.getElement(offset1) === this.getElement(offset2);
	}
}

function joinCloseConsecutiveMoves(moves: LineRangeMapping[]): LineRangeMapping[] {
	if (moves.length === 0) {
		return moves;
	}

	moves.sort((a, b) => a.original.startLineNumber - b.original.startLineNumber);

	const result = [moves[0]];
	for (let i = 1; i < moves.length; i++) {
		const last = result[result.length - 1];
		const current = moves[i];

		const originalDist = current.original.startLineNumber - last.original.endLineNumberExclusive;
		const modifiedDist = current.modified.startLineNumber - last.modified.endLineNumberExclusive;
		const currentMoveAfterLast = originalDist >= 0 && modifiedDist >= 0;

		if (currentMoveAfterLast && originalDist + modifiedDist <= 2) {
			result[result.length - 1] = last.join(current);
			continue;
		}

		result.push(current);
	}
	return result;
}

function removeMovesInSameDiff(changes: DetailedLineRangeMapping[], moves: LineRangeMapping[]) {
	return moves.filter(m => {
		const diffBeforeEndOfMoveOriginal = findLastMonotonous(changes, c => c.original.startLineNumber < m.original.endLineNumberExclusive)
			|| new LineRangeMapping(new LineRange(1, 1), new LineRange(1, 1));
		const diffBeforeEndOfMoveModified = findLastMonotonous(changes, c => c.modified.startLineNumber < m.modified.endLineNumberExclusive);
		return diffBeforeEndOfMoveOriginal !== diffBeforeEndOfMoveModified;
	});
}

function isSpace(charCode: number): boolean {
	return charCode === 32 /* space */ || charCode === 9 /* tab */;
}

/**
 * The lines of a line range, summarized as a character histogram.
 */
class LineRangeFragment {
	private static readonly _chrKeys = new Map<string, number>();

	private static _getKey(chr: string): number {
		let key = this._chrKeys.get(chr);
		if (key === undefined) {
			key = this._chrKeys.size;
			this._chrKeys.set(chr, key);
		}
		return key;
	}

	private readonly _totalCount: number;
	private readonly _histogram: number[] = [];

	constructor(
		readonly range: LineRange,
		lines: string[],
		readonly source: DetailedLineRangeMapping,
	) {
		let counter = 0;
		for (let i = range.startLineNumber - 1; i < range.endLineNumberExclusive - 1; i++) {
			const line = lines[i];
			for (let j = 0; j < line.length; j++) {
				counter++;
				const key = LineRangeFragment._getKey(line[j]);
				this._histogram[key] = (this._histogram[key] || 0) + 1;
			}
			counter++;
			const key = LineRangeFragment._getKey('\n');
			this._histogram[key] = (this._histogram[key] || 0) + 1;
		}
		this._totalCount = counter;
	}

	computeSimilarity(other: LineRangeFragment): number {
		let sumDifferences = 0;
		const maxLength = Math.max(this._histogram.length, other._histogram.length);
		for (let i = 0; i < maxLength; i++) {
			sumDifferences += Math.abs((this._histogram[i] ?? 0) - (other._histogram[i] ?? 0));
		}
		return 1 - (sumDifferences / (this._totalCount + other._totalCount));
	}
}
