/**
 * Binary searches over arrays whose elements are partitioned by `predicate`:
 * it holds for a prefix (or suffix) of the array and not for the rest.
 */

/**
 * Returns the index of the last element for which `predicate` holds, or -1.
 * `predicate` must hold for a prefix of `array`.
 */
export function findLastIdxMonotonous<T>(array: readonly T[], predicate: (item: T) => boolean): number {
	let low = 0;
	let high = array.length - 1;
	while (low <= high) {
		const mid = Math.floor((low + high) / 2);
		if (predicate(array[mid])) {
			low = mid + 1;
		} else {
			high = mid - 1;
		}
	}
	return high;
}

/**
 * Returns the last element for which `predicate` holds.
 * `predicate` must hold for a prefix of `array`.
 */
export function findLastMonotonous<T>(array: readonly T[], predicate: (item: T) => boolean): T | undefined {
	const idx = findLastIdxMonotonous(array, predicate);
	return idx >= 0 ? array[idx] : undefined;
}

/**
 * Returns the index of the first element for which `predicate` holds, or `array.length`.
 * `predicate` must hold for a suffix of `array`.
 */
export function findFirstIdxMonotonousOrArrLen<T>(array: readonly T[], predicate: (item: T) => boolean): number {
	let low = 0;
	let high = array.length - 1;
	while (low <= high) {
		const mid = Math.floor((low + high) / 2);
		if (predicate(array[mid])) {
			high = mid - 1;
		} else {
			low = mid + 1;
		}
	}
	return low;
}

/**
 * Returns the first element for which `predicate` holds.
 * `predicate` must hold for a suffix of `array`.
 */
export function findFirstMonotonous<T>(array: readonly T[], predicate: (item: T) => boolean): T | undefined {
	const idx = findFirstIdxMonotonousOrArrLen(array, predicate);
	return idx < array.length ? array[idx] : undefined;
}
